// The three habits, filled in when the template is added.
const HABITS = [{{first}}, {{second}}, {{third}}];
const PINE = '#13221a';
const MINT = '#dff5e8';
const LEAF = '#6fdc9f';
const ON = '#2fbf80';
const GRID = 'M5 3h4a2 2 0 0 1 2 2v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Z M15 3h4a2 2 0 0 1 2 2v4a2 2 0 0 1-2 '
  + '2h-4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Z M5 13h4a2 2 0 0 1 2 2v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4a2 2 0 0 1 2-2Z M15 '
  + '13h4a2 2 0 0 1 2 2v4a2 2 0 0 1-2 2h-4a2 2 0 0 1-2-2v-4a2 2 0 0 1 2-2Z';

// `s` is one prototype unit at the squares' scale.
function square(on, s) {
  return { type: 'rect', cornerRadius: 4 * s, fill: on ? ON : '#FFFFFF1A', frame: { width: 15 * s, height: 15 * s } };
}

// Today's square is the button: it marks the day, or clears it once marked.
function today(n, row, s) {
  return row
    ? { type: 'button', action: 'uncheck', rowId: row.id, children: [square(true, s)] }
    : { type: 'button', action: 'check' + n, children: [square(false, s)] };
}

function render(ctx) {
  // Sizes are in the prototype's units: a widget is 170 of them tall.
  const u = ctx.height / 170;
  const d = ctx.data;
  const wide = ctx.family === 'medium';
  const shown = wide ? 14 : 5;
  // The squares keep the prototype's size and the name column takes the rest of the row, so the last square sits
  // under "today" at any width. Where that would leave a name under the prototype's 70 units, the squares shrink
  // instead; 70 also fits the longest habit name a person can type as one word.
  const gap = 4;
  const room = ctx.width / u - 32 - gap;
  const grid = shown * 15 + (shown - 1) * 3.5;
  const scale = Math.min(1, (room - 70) / grid);
  const nameWidth = room - grid * scale;
  const s = scale * u;
  const habits = HABITS.map((name, i) => ({ name, n: i + 1, days: d['days' + (i + 1)],
    today: d['today' + (i + 1)], streak: d['streak' + (i + 1)] }));
  const best = habits.reduce((a, b) => (b.streak > a.streak ? b : a));

  const line = (habit) => ({ type: 'hstack', spacing: gap * u, children: [
    { type: 'text', value: habit.name, size: 13 * u, weight: 'bold', color: MINT, lineLimit: 1, minScale: 0.4,
      frame: { width: nameWidth * u, height: 16 * u, alignment: 'leading' } },
    { type: 'hstack', spacing: 3.5 * s, children: habit.days.slice(-shown).map((day, i) => (i === shown - 1
      ? today(habit.n, habit.today, s)
      : square(day.count > 0, s))) },
  ] });

  return {
    type: 'zstack', align: 'topLeading',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: PINE,
    children: [
      { type: 'vstack', align: 'leading', spacing: 0, padding: { top: 15 * u, leading: 16 * u, trailing: 16 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
        children: [
          { type: 'hstack', spacing: 5 * u, frame: { height: 16 * u }, children: [
            { type: 'path', d: GRID, viewBox: [0, 0, 24, 24], fill: LEAF, frame: { width: 15 * u, height: 15 * u } },
            { type: 'text', value: wide ? 'Last two weeks' : 'Last 5 days', size: 13 * u, weight: 'bold',
              color: LEAF, lineLimit: 1, minScale: 0.8 },
            { type: 'spacer', minLength: 0 },
            { type: 'text', value: 'today', size: 13 * u, weight: 'semibold', color: LEAF, opacity: 0.55 },
          ] },
          { type: 'vstack', align: 'leading', spacing: 8 * u, padding: { top: 13.5 * u }, children: habits.map(line) },
        ] },
      { type: 'text', accent: true,
        value: best.streak > 0
          ? best.name + ': ' + best.streak + (best.streak === 1 ? ' day' : ' days') + ' in a row'
          : 'Tap today\'s square when it\'s done',
        size: 12.5 * u, weight: 'bold', color: MINT, opacity: 0.7, lineLimit: 1, minScale: 0.6,
        padding: { leading: 16 * u, trailing: 16 * u, bottom: 17 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomLeading' } },
    ],
  };
}
